// Differential checks of FourSchemes-pbo.js against Lean, generated by leanscript --check
import * as M from "./FourSchemes-pbo.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  // a list of cons cells (`ListRepr.taggedUnion`) is shown as its elements
  if (v !== null && typeof v === "object" && (v.tag === 0 || v.tag === 1)) {
    const a = [];
    for (; v.tag === 1; v = v._2) a.push(v._1);
    return show(a);
  }
  // a record (a structure-like type) is shown as its fields: `{a, b}`
  if (v !== null && typeof v === "object" && !("tag" in v) && "_1" in v) {
    const fs = [];
    for (let i = 1; ("_" + i) in v; i++) fs.push(show(v["_" + i]));
    return "{" + fs.join(", ") + "}";
  }
  return String(v);
}
// a union `{ tag: i, _1: …, … }` of leaf fields is shown as `i(…, …)`
function showUnion(v) {
  const fs = [];
  for (let i = 1; ("_" + i) in v; i++) fs.push(show(v["_" + i]));
  return v.tag + "(" + fs.join(", ") + ")";
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("sumAcc(0, 0)", () => M.sumAcc(0, 0), "0", false);
check("sumAcc(0, 2)", () => M.sumAcc(0, 2), "2", false);
check("sumAcc(1, 1)", () => M.sumAcc(1, 1), "2", false);
check("sumAcc(2, 0)", () => M.sumAcc(2, 0), "3", false);
check("sumAcc(0, 13)", () => M.sumAcc(0, 13), "13", false);
check("sumAcc(1, 5)", () => M.sumAcc(1, 5), "6", false);
check("sumAcc(2, 2)", () => M.sumAcc(2, 2), "5", false);
check("sumAcc(5, 1)", () => M.sumAcc(5, 1), "16", false);
check("sumAcc(13, 0)", () => M.sumAcc(13, 0), "91", false);
check("sumAcc(2, 13)", () => M.sumAcc(2, 13), "16", false);
check("sumAcc(5, 5)", () => M.sumAcc(5, 5), "20", false);
check("sumAcc(13, 2)", () => M.sumAcc(13, 2), "93", false);
check("sumAcc(13, 13)", () => M.sumAcc(13, 13), "104", false);
check("factD(0)", () => M.factD(0), "1", false);
check("factD(1)", () => M.factD(1), "1", false);
check("factD(2)", () => M.factD(2), "2", false);
check("factD(5)", () => M.factD(5), "120", false);
check("factD(13)", () => M.factD(13), "6227020800", false);

console.log(`FourSchemes-pbo.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
